;   INPUT PARAMS: SCDLFG,STIMER,SAUCER,SCANGL,SAPOSX,SAPOSY
;   OUTPUT PARAMS: SAPOSX,SAPOSY,SAINCX,SAINCX,SCANGL,SINT,STIMTER
