;------------------------------------------------------------------------------
; TRACK - TRACKING ROUTINE
;   BLOCK NAME: TRACK
;   DESCRIPTION: THIS ROUTINE COMPUTE THE VECTOR
;   BETWEEN THE ROBOT TANK AND THE PLAYER
;   CONTROLLED TANK, AND USING THE ARCTANGENT
;   FUNCTION, RETURNS THE ANGLE TO DIRECT THE
;   ROBOT TANK IN.
;   INPUT PARAMS: TPOSX,TPOSY FOR BOTH TANKS
;   OUTPUT PARAMS: (A)=NEW ANGLE TO DIRECT ROBOT
;   TEMP1 =ABS VALUE(Y)
;   TEMP2 =ABS VALUE(X)
;   REGISTERS: A,X,Y
;   SUBROUTINES: NONE
;------------------------------------------------------------------------------
TRACK:
L6810:  LDY  #$00                   ;C INITIALIZE QUADRANT
L6812:  SEC                         ;C HIS XPOS MINUS ROBOT XPOS
L6813:  LDA  TPOSX
L6815:  SBC  TPOSX+2
L6817:  STA  TEMP1
L6819:  LDA  TPOSX+1
L681B:  SBC  TPOSX+3
L681D:  STA  TEMP1+1
L681F:  BPL  TRACK_10               ;D IF POSITIVE
L6821:  JSR  ABSTMP                 ;C TAKE ABSOLUTE VALUE
L6824:  INY                         ;C X < 0 MEANS QUAD 2 OR 3

TRACK_10:
L6825:  LDA  TEMP1                  ;C MOVE ABSOLUTE VALUE
L6827:  STA  TEMP2
L6829:  LDA  TEMP1+1
L682B:  STA  TEMP2+1
L682D:  LDA  TEMP1+1
L682F:  SEC                         ;C HIS YPOS MINUS ROBOT YPOS
L6830:  LDA  TPOSY
L6832:  SBC  TPOSY+2
L6834:  STA  TEMP1
L6836:  LDA  TPOSY+1
L6838:  SBC  TPOSY+3
L683A:  STA  TEMP1+1
L683C:  BPL  TRACK_20               ;D IF POSITIVE
L683E:  JSR  ABSTMP                 ;C ABSOLUTE VALUE
L6841:  TYA                         ;C Y < 0 MEANS QUAD 2 OR 3
L6842:  BEQ  TRACK_12
L6844:  INY
L6845:  BNE  TRACK_20

TRACK_12:
L6847:  LDY  #$03

TRACK_20:
L6849:  LDA  TEMP1                  ;D IF X > Y
L684B:  CMP  TEMP2
L684D:  BNE  TRACK_25               ;(IF NOT EQUAL)
L684F:  LDA  TEMP1+1
L6851:  CMP  TEMP2+1
L6853:  BEQ  TRACK_22               ;D IF X=Y
L6855:  SEC
L6856:  BCS  TRACK_25

TRACK_22:
L6858:  LDA  #$20                   ;C USE 45 DEG
L685A:  BNE  TRACK_45

TRACK_25:
L685C:  LDA  TEMP1+1
L685E:  SBC  TEMP2+1
L6860:  PHP                         ;(SAVE STATUS)
L6861:  BCC  TRACK_30

TRACK_28:
L6863:  LDA  TEMP1                  ;C COMPUTE X/Y
L6865:  STA  XPL
L6868:  LDA  TEMP1+1
L686A:  STA  XPH
L686D:  LDA  TEMP2
L686F:  STA  DIVOUT
L6872:  LDA  TEMP2+1
L6874:  STA  DIVOUT+1
L6877:  STA  ZDIV
L687A:  JMP  TRACK_40

TRACK_30:
L687D:  LDA  TEMP2                  ;C COMPUTE Y/X
L687F:  STA  XPL
L6882:  LDA  TEMP2+1
L6884:  STA  XPH
L6887:  LDA  TEMP1
L6889:  STA  DIVOUT
L688C:  LDA  TEMP1+1
L688E:  STA  DIVOUT+1
L6891:  STA  ZDIV

TRACK_40:
L6894:  JSR  WAIT
L6897:  STA  TEMP3
L6899:  LDA  MOUTHI
L689C:  LSR                         ;C DOUBLE SHIFT RIGHT
L689D:  ROR  TEMP3
L689F:  LSR
L68A0:  ROR  TEMP3
L68A2:  LDX  TEMP3
L68A4:  LDA  ARCTAN,X               ;C GET ARCTANGENT
L68A7:  PLP                         ;D IF Y/X
L68A8:  BCC  TRACK_45
L68AA:  STA  TEMP3                  ;C SUBTRACT FROM 90 DEGREES
L68AC:  LDA  #$40
L68AE:  SBC  TEMP3

TRACK_45:
L68B0:  TAX                         ;C SET UP FOR DO CASE
L68B1:  TYA
L68B2:  ASL
L68B3:  TAY
L68B4:  LDA  TTAB+1,Y
L68B7:  PHA
L68B8:  LDA  TTAB,Y
L68BB:  PHA
L68BC:  TXA
L68BD:  RTS

TTAB:
L68BE:  .word T_0-1, T_1-1, T_2-1, T_3-1

;------------------------------------------------------------------------------
; T_1 - [note] TTAB quadrant-1 entry: negate the arctangent-table angle (two's complement), then falls into
;   T_2 to also flip it 180 degrees.
;------------------------------------------------------------------------------
T_1:
L68C6:  CLC                         ;C PFM
L68C7:  EOR  #$FF
L68C9:  ADC  #$01

;------------------------------------------------------------------------------
; T_2 - [note] TTAB quadrant-2 entry: flip the arctangent-table angle 180 degrees (EOR #$80), then JMP T_0
;   (RTS) with the finished angle in A.
;------------------------------------------------------------------------------
T_2:
L68CB:  EOR  #$80
L68CD:  JMP  T_0

;------------------------------------------------------------------------------
; T_3 - [note] TTAB quadrant-3 entry: negate the arctangent-table angle (two's complement), then falls into
;   T_0 (RTS).
;------------------------------------------------------------------------------
T_3:
L68D0:  CLC
L68D1:  EOR  #$FF
L68D3:  ADC  #$01

;------------------------------------------------------------------------------
; T_0 - [note] TTAB quadrant-0 entry, and the shared exit for T_2/T_3: RTS with the finished angle in A.
;------------------------------------------------------------------------------
T_0:
L68D5:  RTS

;------------------------------------------------------------------------------
; OBJOBJ - OBJECT-OBJECT COLLISION DETECT
;   ARCTANGENT TABLE CREATED 5-SEP-79
;   BLOCK NAME: OBJOBJ
;   DESCRIPTION: THIS ROUTINE WILL CHECK FOR
;   COLLISION BETWEEN TANKS AND PLAYFIELD
;   OBJECTS
;   INPUT: (X)=0 FOR PLAYER TANK
;   (X)=2 FOR ROBOT TANK
;   TPOSX,TPOSX,PTBLO1,PTBLX1,PTBLY1,PROXTB
;   OUTPUT PARMS: CARRY SET COLLISION, 0=NONTANK COLLISION, -1=TANK COLLISION IN(A)
;   REGISTERS: DSTNCE
;   USES: TEMP1,TEMP2,TEMP3
;------------------------------------------------------------------------------
OBJOBJ:
L68D6:  CLC
L68D7:  STX  TEMP1                  ;L SAVE X
L68D9:  LDA  TPOSX,X                ;C SET UP MATH BOX
L68DB:  STA  ACOS
L68DE:  LDA  TPOSX+1,X
L68E0:  STA  ACOS+1
L68E3:  LDA  TPOSY,X
L68E5:  STA  BSIN
L68E8:  LDA  TPOSY+1,X
L68EA:  STA  BSIN+1
L68ED:  LDY  #$00

OBJOBJ_10:
L68EF:  LDA  PTBLO1,Y               ;D IF DONE
L68F2:  BMI  OBJOBJ_50
L68F4:  LDA  PTBLX1,Y               ;C GET DISTANCE TO OBJECT
L68F7:  STA  TPOSXT
L68FA:  LDA  PTBLX1+1,Y
L68FD:  STA  TPOSXT+1
L6900:  LDA  PTBLY1,Y
L6903:  STA  TPOSYT
L6906:  LDA  PTBLY1+1,Y
L6909:  STA  DSTNCE
L690C:  CMP  ($00,X)
L690E:  LDA  MOUTLO
L6911:  STA  TEMP3
L6913:  LDA  MOUTHI
L6916:  STA  TEMP3+1
L6918:  TXA                         ;D IF ROBOT
L6919:  BNE  OBJOBJ_20              ;C COLLIDE SO WE CAN SEE OBJECT
L691B:  LDA  #$80
L691D:  CMP  TEMP3
L691F:  LDA  #$04
L6921:  BNE  OBJOBJ_30

OBJOBJ_20:
L6923:  LDA  PTBLO1,Y
L6926:  ASL
L6927:  TAX
L6928:  BIT  R2D3FL
L692A:  BPL  OBJOBJ_25
L692C:  LDA  TEMP3+1                ;C 3/4 TANK RADIUS
L692E:  CMP  #$80
L6930:  ROR
L6931:  STA  TEMP2+1
L6933:  LDA  TEMP3
L6935:  ROR
L6936:  CLC
L6937:  ADC  TEMP3
L6939:  STA  TEMP3
L693B:  LDA  TEMP2+1
L693D:  ADC  TEMP3+1
L693F:  STA  TEMP3+1
L6941:  BCC  OBJOBJ_25
L6943:  LDX  TEMP1
L6945:  BCS  OBJOBJ_40

OBJOBJ_25:
L6947:  LDA  PROXTB,X               ;D IF COLLISION
L694A:  CMP  TEMP3
L694C:  LDA  PROXTB+1,X
L694F:  LDX  TEMP1

OBJOBJ_30:
L6951:  SBC  TEMP3+1
L6953:  LDA  #$00                   ;C SET FOR NONTANK COLLISION
L6955:  BCS  OBJOBJ_60

OBJOBJ_40:
L6957:  INY                         ;C NEXT OBJECT
L6958:  INY
L6959:  BNE  OBJOBJ_10              ;B

OBJOBJ_50:
L695B:  LDA  COLFLG                 ;D IF EITHER IN COLLISION
L695D:  ORA  COLFLG+2
L695F:  BNE  OBJOBJ_60
L6961:  TXA
L6962:  EOR  #$02
L6964:  TAX
L6965:  LDA  TPOSX,X
L6967:  STA  TPOSXT
L696A:  LDA  TPOSX+1,X
L696C:  STA  TPOSXT+1
L696F:  LDA  TPOSY,X
L6971:  STA  TPOSYT
L6974:  LDA  TPOSY+1,X
L6976:  STA  DSTNCE
L6979:  CMP  ($00,X)                ;WASTE TIME
L697B:  LDA  MOUTLO
L697E:  STA  TEMP3
L6980:  LDA  MOUTHI
L6983:  STA  TEMP3+1
L6985:  LDA  #$05

OBJOBJ_54:
L6987:  BIT  R2D3FL                 ;SMALLER COLL. RADIUS FOR R2D3
L6989:  BPL  OBJOBJ_55
L698B:  LDA  #$03

OBJOBJ_55:
L698D:  SEC
L698E:  SBC  TEMP3+1                ;CARRY SET IF COLL.
L6990:  LDA  #$FF                   ;C INDICATE TANKS

OBJOBJ_60:
L6992:  LDX  TEMP1                  ;L RESTORE X
L6994:  RTS

PROXTB:
L6995:  .word $0340, $0340
L6999:  .word $0000                 ;.REPT 10.
L699B:  .word $0000
L699D:  .word $0000
L699F:  .word $0000
L69A1:  .word $0000
L69A3:  .word $0000
L69A5:  .word $0000
L69A7:  .word $0000
L69A9:  .word $0000
L69AB:  .word $0000
L69AD:  .word $0400, $0000, $0000, $03C0

;------------------------------------------------------------------------------
; TR7CHK - CHECK FOR HIGH POWERED TANK ROBOT
;   BLOCK NAME: TR7CHK
;   BLOCK DESCRIPTION: DETERMINES IF WE HAVE OR SHOULD HAVE
;   THE TR7 INSTEAD OF THE OLD CLVUKER
;   INPUT PARAMS: NOR2D3
;   OUTPUT PARAMS: CARRY SET=TR7
;   REGISTERS USED: A
;------------------------------------------------------------------------------
TR7CHK:
L69B5:  CLC                         ;C ASSUME REGULAR TANK
L69B6:  LDA  NOR2D3
L69B9:  BMI  TR7CHK_10
L69BB:  CMP  #$05                   ;C CLEAR CARRY FOR TANK

TR7CHK_10:
L69BD:  RTS

;------------------------------------------------------------------------------
; ROBCHK - ROBOT RESET CHECK
;   BLOCK NAME: ROBCHK
;   DESCRIPTION: ROBCHK WILL RANDOMNLY RESET HIS GOAL AND TAKE HIM
;   OUT OF ATTACK MODE FOR A SHORT TIME, AS
;   WELL AS MOVING HIM TO A NEW POSITION.
;   INPUT: COLFLG
;   OUTPUT: TPOSX,TPOSY,COLFLG,STATE,ACTION,RGOAL
;   REGISTERS: A,X
;   SUBROUTINES: RAND, OBJBOJ,ROBOT
;------------------------------------------------------------------------------
ROBCHK:
L69BE:  LDA  GOVER
L69C0:  BNE  TANKCK
L69C2:  LDA  HITS+1
L69C4:  BNE  ROBCHK_10
L69C6:  LDA  OPTION
L69C9:  LSR
L69CA:  LSR
L69CB:  AND  #$03
L69CD:  TAX
L69CE:  LDA  HITS                   ;D IF NOT BUZZ BOMB
L69D0:  CMP  MISLVL,X
L69D3:  BCC  TANKCK

ROBCHK_10:
L69D5:  LDY  PRAND                  ;C FUDGE POKEY RANDOMNESS
L69D8:  TYA
L69D9:  EOR  OLDRND
L69DC:  STY  OLDRND
L69DF:  LSR
L69E0:  BCC  TANKCK
L69E2:  LDA  #$02                   ;C SET SHORTER WAIT TIME
L69E4:  STA  TIMOUT
L69E6:  BNE  R2D3CK                 ;B

;------------------------------------------------------------------------------
; TANKCK - [note] ROBCHK: reset the robot as a plain tank - new random RGOAL, clear R2D3FL/COLFLG+2, short
;   reaction/timeout (ACTION=TIMOUT=1); in attract mode also computes a random placement window
;   ahead of the player, reaching ROB1 by a BEQ; otherwise (TANKCK_10) LDA #$0F and JMP ROB1 to
;   pick the new position.
;------------------------------------------------------------------------------
TANKCK:
L69E8:  LDA  PRAND                  ;C RESET GOAL
L69EB:  STA  RGOAL
L69ED:  LDA  #$00
L69EF:  STA  R2D3FL                 ;C RESET TO TANK
L69F1:  STA  COLFLG+2               ;C OUT OF COLLISION
L69F3:  LDA  #$01                   ;C SET REACTION TIME SHORT
L69F5:  STA  ACTION
L69F7:  STA  TIMOUT
L69F9:  BIT  ATRACT                 ;D IF ATRACT PUT TANK IN FRONT
L69FB:  BPL  TANKCK_10
L69FD:  LDA  HITS+1
L69FF:  BNE  TANKCK_6
L6A01:  SEC
L6A02:  LDA  HITS                   ;C DETERMINE WINDOW FOR TANK
L6A04:  SBC  HITS+2
L6A06:  BCC  TANKCK_10
L6A08:  BEQ  TANKCK_10
L6A0A:  CMP  #$07
L6A0C:  BCC  TANKCK_8

TANKCK_6:
L6A0E:  LDA  #$07

TANKCK_8:
L6A10:  LSR
L6A11:  BEQ  TANKCK_10
L6A13:  TAX
L6A14:  LDA  #$0F

TANKCK_9:
L6A16:  SEC
L6A17:  ROL
L6A18:  DEX
L6A19:  BNE  TANKCK_9
L6A1B:  BEQ  ROB1

TANKCK_10:
L6A1D:  LDA  #$0F
L6A1F:  JMP  ROB1

;------------------------------------------------------------------------------
; R2D3CK - [note] ROBCHK: (re)spawn the buzz bomber (R2D3) instead of a tank - increments NOR2D3, sets one
;   explosion-table Z slot (EXPOSZ+$C/$D) to STARTZ (the buzz bomber's starting depth), sets
;   STATE=$80 (the same 'attacking' flag R_ATCK sets - collision retreat is tracked in STATE's
;   bits 0-1, not bit 7), forces the engine sound channels to their idle frequencies, and sets
;   R2D3FL=-1.  Falls straight into ROB1 (no branch).
;------------------------------------------------------------------------------
R2D3CK:
L6A22:  INC  NOR2D3                 ;C THIS WILL SET NOR2D3 TO 0 FOR FIRST
L6A25:  LDA  #STARTZ/$100
L6A27:  STA  EXPOSZ+$D
L6A2A:  LDA  #STARTZ&$FF
L6A2C:  STA  EXPOSZ+$C
L6A2F:  LDA  #$80
L6A31:  STA  STATE
L6A33:  LDX  #$FF
L6A35:  STX  CHAN3F
L6A38:  DEX
L6A39:  STX  CHAN4F
L6A3C:  LDA  #$FF
L6A3E:  STA  R2D3FL                 ;C PUT BUZZ BOMB IN FRONT TO HIM
L6A40:  LDA  PRAND
L6A43:  AND  #$0F

ROB1:
L6A45:  STA  TEMP1
L6A47:  LDA  PRAND
L6A4A:  AND  TEMP1
L6A4C:  BIT  S_INTCT
L6A4E:  BVS  ROB1_20
L6A50:  EOR  #$FF

ROB1_20:
L6A52:  CLC
L6A53:  ADC  TANGLE
L6A55:  STA  TEMP1
L6A57:  JSR  COS
L6A5A:  STA  TEMP2                  ;C X=X-1/4*X
L6A5C:  STA  X1
L6A5E:  STX  X1+1
L6A60:  TXA
L6A61:  CMP  #$80
L6A63:  ROR
L6A64:  ROR  TEMP2
L6A66:  CMP  #$80
L6A68:  ROR
L6A69:  ROR  TEMP2
L6A6B:  STA  TEMP2+1
L6A6D:  LDA  X1
L6A6F:  SEC
L6A70:  SBC  TEMP2
L6A72:  STA  TEMP2
L6A74:  LDA  X1+1
L6A76:  SBC  TEMP2+1
L6A78:  TAX
L6A79:  BIT  R2D3FL
L6A7B:  BMI  ROB1_45
L6A7D:  LDA  PRAND
L6A80:  LSR
L6A81:  PHP
L6A82:  TXA
L6A83:  BCC  ROB1_45
L6A85:  CMP  #$80
L6A87:  ROR
L6A88:  ROR  TEMP2

ROB1_45:
L6A8A:  STA  TEMP2+1
L6A8C:  LDA  TEMP1
L6A8E:  JSR  SIN
L6A91:  STA  TEMP1                  ;C Y=Y-1/4*Y
L6A93:  STA  Y1
L6A95:  STX  Y1+1
L6A97:  TXA
L6A98:  CMP  #$80
L6A9A:  ROR
L6A9B:  ROR  TEMP1
L6A9D:  CMP  #$80
L6A9F:  ROR
L6AA0:  ROR  TEMP1
L6AA2:  STA  TEMP1+1
L6AA4:  SEC
L6AA5:  LDA  Y1
L6AA7:  SBC  TEMP1
L6AA9:  STA  TEMP1
L6AAB:  LDA  Y1+1
L6AAD:  SBC  TEMP1+1
L6AAF:  BIT  R2D3FL
L6AB1:  BMI  ROB1_49
L6AB3:  PLP
L6AB4:  BCC  ROB1_49
L6AB6:  CMP  #$80
L6AB8:  ROR
L6AB9:  ROR  TEMP1

ROB1_49:
L6ABB:  STA  TEMP1+1                ;C SET UP STARTING POS
L6ABD:  CLC
L6ABE:  LDA  TPOSX
L6AC0:  ADC  TEMP2
L6AC2:  STA  TPOSX+2
L6AC4:  LDA  TPOSX+1
L6AC6:  ADC  TEMP2+1
L6AC8:  STA  TPOSX+3
L6ACA:  LDA  TPOSY
L6ACC:  CLC
L6ACD:  ADC  TEMP1
L6ACF:  STA  TPOSY+2
L6AD1:  LDA  TPOSY+1
L6AD3:  ADC  TEMP1+1
L6AD5:  STA  TPOSY+3
L6AD7:  BIT  R2D3FL
L6AD9:  BPL  ROB1_50
L6ADB:  JSR  TRACK                  ;C SET UP STARTING ANGLE
L6ADE:  STA  TANGLE+2
L6AE0:  STA  RGOAL

ROB1_50:
L6AE2:  LDA  #$00
L6AE4:  STA  EIRNGE
L6AE6:  STA  FTIMER
L6AE8:  RTS

;------------------------------------------------------------------------------
; DRADAR - DISPLAY RADAR
;   BLOCK NAME: DRADAR
;   DESCRIPTION: THIS ROUTINE WILL DISPLAY RADAR SWEEP
;   AND BLIP OF OTHER TANK, IF WITH FIRING RANGE
;   INPUT PARAMETERS: SANGLE,(TEMP1,TEMP2) SET UP BY TRACK ROUTINE
;   OUTPUT PARAMETERS: TDIST
;   REGISTERS: A,X,Y
;   SUBROUTINES: TRACK,SIN,COS,VGLABS,VGVCTR
;------------------------------------------------------------------------------
DRADAR:
L6AE9:  LDX  #<RDRING               ;LXL RDRING
L6AEB:  LDA  #>RDRING               ;LAH RDRING
L6AED:  JSR  VGJSRL
L6AF0:  LDA  #$00
L6AF2:  STA  XCOMP+1
L6AF4:  STA  YCOMP+1
L6AF6:  STA  CURNTX+1
L6AF8:  LDA  #$0B                   ;C INCREMENT SWEEP ANGLE
L6AFA:  CLC
