L6AFD:  STA  SANGLE
L6AFF:  JSR  SIN                    ;C SIN/2
L6B02:  TXA
L6B03:  CMP  #$80
L6B05:  ROR
L6B06:  STA  XCOMP
L6B08:  STA  CURNTX
L6B0A:  BPL  DRADAR_10
L6B0C:  LDA  #$FF
L6B0E:  STA  XCOMP+1
L6B10:  STA  CURNTX+1

DRADAR_10:
L6B12:  LDA  SANGLE                 ;C COS/2
L6B14:  JSR  COS
L6B17:  TXA
L6B18:  CMP  #$80
L6B1A:  ROR
L6B1B:  STA  XCOMP+2
L6B1D:  BPL  DRADAR_20
L6B1F:  LDA  #$FF
L6B21:  STA  XCOMP+3

DRADAR_20:
L6B23:  LDA  #$A0                   ;C DRAW BRIGHT VECTOR
L6B25:  STA  VGBRIT
L6B27:  LDA  #CENTRY&$FF
L6B29:  CLC
L6B2A:  ADC  XCOMP+2
L6B2C:  STA  CURNTY
L6B2E:  LDA  #CENTRY/$100
L6B30:  ADC  XCOMP+3
L6B32:  STA  CURNTY+1
L6B34:  JSR  VGVTR2
L6B37:  LDA  COLFLG+2               ;D IF NOT EXPLODING
L6B39:  BEQ  DRADAR_21
L6B3B:  LDA  #$00
L6B3D:  STA  CHAN3V
L6B40:  STA  CHAN4V
L6B43:  RTS

DRADAR_21:
