L6B47:  EOR  #$80
L6B49:  SEC
L6B4A:  STA  GARBAG                 ;C RELATIVE ANGLE OF ROBOT
L6B4C:  LDA  TANGLE
L6B4E:  SBC  GARBAG
L6B50:  STA  GARBAG
L6B52:  LDA  SANGLE                 ;D IF NOT ON SWEEP LINE
L6B54:  SEC
L6B55:  SBC  GARBAG
L6B57:  BMI  DRADAR_23
L6B59:  CMP  #$0C
L6B5B:  BCS  DRADAR_23
L6B5D:  LDA  #$F0                   ;C SET BRIGHTNESS OF BLIP
L6B5F:  STA  BLIP

DRADAR_23:
L6B62:  LDA  TEMP1                  ;C COMPUTE DISTANCE
L6B64:  STA  TPOSXT
L6B67:  LDA  TEMP1+1
L6B69:  STA  TPOSXT+1
L6B6C:  LDA  TEMP2
L6B6E:  STA  TPOSYT
L6B71:  LDA  TEMP2+1
L6B73:  STA  TPOSYT+1
L6B76:  STA  DST2
L6B79:  CMP  ($00,X)
L6B7B:  LDA  MOUTLO
L6B7E:  STA  TEMP3
L6B80:  LDA  MOUTHI
L6B83:  STA  TDIST
L6B86:  TAX
L6B87:  BMI  DRADAR_24
L6B89:  LSR                         ;C SET VOLUME
L6B8A:  LSR
L6B8B:  LSR
L6B8C:  AND  #$0F
L6B8E:  EOR  #$AF
L6B90:  BIT  R2D3FL
L6B92:  BMI  DRADAR_25

DRADAR_24:
L6B94:  LDA  #$00

DRADAR_25:
L6B96:  STA  CHAN3V
L6B99:  STA  CHAN4V
L6B9C:  TXA
L6B9D:  STA  XMATRX
L6BA0:  CMP  #$80                   ;D IF OUT OF RANGE
L6BA2:  BCC  DRADAR_35
L6BA4:  LDA  #$00
L6BA6:  STA  EIRNGE                 ;C OUT OF RANGE
L6BA8:  BIT  R2D3FL
L6BAA:  BPL  DRADAR_30
L6BAC:  LDA  TIMOUT                 ;D IF NOT TIMED OUT ON R2D3'S
L6BAE:  CMP  #$04
L6BB0:  BCC  DRADAR_27
L6BB2:  JSR  TANKCK
L6BB5:  JMP  DR_BLP

DRADAR_27:
L6BB8:  JSR  R2D3CK

DRADAR_30:
L6BBB:  JMP  DR_BLP

DRADAR_35:
