L6BDD:  STA  BSIN
L6BE0:  STX  BSIN+1
L6BE3:  LDA  #CENTRX&$FF
L6BE5:  STA  TPOSXT
L6BE8:  LDA  #CENTRX/$100
L6BEA:  STA  TPOSXT+1
L6BED:  LDA  #CENTRY&$FF
L6BEF:  STA  TPOSYT
L6BF2:  LDA  #CENTRY/$100
L6BF4:  STA  TPOSYT+1
L6BF7:  LDA  #$00
L6BF9:  STA  XMATRX+1
L6BFC:  STA  VGBRIT                 ;C SET ZERO BRITE
L6BFE:  STA  YMATRX                 ;C START MATRIX MULT
L6C01:  STA  YSTRT2
L6C04:  JSR  WAIT                   ;C SCALE RESLT
L6C07:  STA  DXP
L6C0A:  LDA  MOUTLO
L6C0D:  SEC
L6C0E:  SBC  CURNTX
L6C10:  STA  XCOMP
L6C12:  LDA  MOUTHI
L6C15:  STA  DYPH                   ;RESTAT MULTIPLIER
L6C18:  SBC  CURNTX+1
L6C1A:  STA  XCOMP+1
L6C1C:  LDA  MOUTLO
L6C1F:  SEC
L6C20:  SBC  CURNTY
L6C22:  STA  YCOMP
L6C24:  LDA  MOUTHI
L6C27:  SBC  CURNTY+1
L6C29:  STA  YCOMP+1
L6C2B:  JSR  VGVTR2
L6C2E:  LDA  BLIP                   ;C DRAW BLIP
L6C31:  AND  #$E0
L6C33:  JSR  VGDOT
L6C36:  LDA  VGBRIT
L6C38:  JSR  VGDOT
L6C3B:  BIT  ATRACT                 ;D IF IN GAME
L6C3D:  BMI  D_5
L6C3F:  BIT  LOGO                   ;D IF LOGO IS BEING DRAWN
L6C42:  BMI  D_10

D_5:
L6C44:  LDA  #$02
L6C46:  AND  FRAME
L6C48:  BEQ  D_10
L6C4A:  LDX  #ERANGE                ;C INDICATE IN RANGE
L6C4C:  JSR  MSGS

D_10:
L6C4F:  LDA  EIRNGE                 ;D IF ALREADY IN RANGE
L6C51:  BNE  DR_BLP                 ;C DRAW BLIP
L6C53:  INC  EIRNGE                 ;C INDICATE IN RANGE
L6C55:  LDA  #WARNG                 ;C OUTPUT WARNING SOUND
L6C57:  JSR  SNDON

DR_BLP:
L6C5A:  LDA  BLIP                   ;D IF SWEEP WAY PAST
L6C5D:  BEQ  DR_RTN
L6C5F:  SEC
L6C60:  SBC  #$08
L6C62:  STA  BLIP

DR_RTN:
L6C65:  RTS

;------------------------------------------------------------------------------
; SHUPDT - UPDATE SHELL POSITION
;   BLOCK NAME: SHUPDT
;   DESCRIPTION: UPDATES SHELLS POSITION
;   INPUT PARAMS: SHELLX,SHELLY,SINCX,SINCY
;   OUTPUT PARAMS: SHELLX,SHELLY
;   REGISTERS: A,X
;------------------------------------------------------------------------------
SHUPDT:
L6C66:  LDX  #$02                   ;C START WITH SECOND SHELL

SHUPDT_10:
L6C68:  LDA  FIRECT,X               ;D IF SHELL NOT IN AIR
L6C6A:  BEQ  SHUPDT_20
L6C6C:  BMI  SHUPDT_20
L6C6E:  DEC  FIRECT,X               ;C RANGE SHELL
L6C70:  CLC
L6C71:  LDA  SHELLX,X               ;C UPDATE SHELL'S X POS
L6C73:  ADC  SINCX,X
L6C75:  STA  SHELLX,X
L6C77:  LDA  SHELLX+1,X
L6C79:  ADC  SINCX+1,X
L6C7B:  STA  SHELLX+1,X
L6C7D:  LDA  SHELLY,X               ;C UPDATE SHELL'S Y POS
L6C7F:  CLC
L6C80:  ADC  SINCY,X
L6C82:  STA  SHELLY,X
L6C84:  LDA  SHELLY+1,X
L6C86:  ADC  SINCY+1,X
L6C88:  STA  SHELLY+1,X

SHUPDT_20:
L6C8A:  DEX
L6C8B:  DEX
L6C8C:  BEQ  SHUPDT_10
L6C8E:  RTS

CHKS5:
L6C8F:  .byte $6B

;.SBTTL MESSAGE ROUTINE

LNGTBL:
;BLOCK NAME: MSGS
;DESCRIPTION: WILL OUTPUT SPECIFIED MESSAGE TO SPECIFIED LOCATION ON SCREEN
;INPUT PARAMS: (X)=MESSAGE # * 2
;OUTPUT PARAMS: NONE
;REGISTERS: A,X,Y
L6C90:  .word ENGLISH-1, GERMAN-1, FRENCH-1, SPANSH-1

;------------------------------------------------------------------------------
; MSGS - C OUTPUT BONUS MESSAGE  (comment at the call)
;------------------------------------------------------------------------------
MSGS:
L6C98:  LDA  OPTION                 ;D DO CASE LANGUAGE
L6C9B:  ROL
L6C9C:  ROL
L6C9D:  ROL
L6C9E:  ROL
L6C9F:  AND  #$06
L6CA1:  TAY
L6CA2:  LDA  LNGTBL+1,Y
L6CA5:  PHA
L6CA6:  LDA  LNGTBL,Y
L6CA9:  PHA
L6CAA:  RTS

;------------------------------------------------------------------------------
; SPANSH - [note] MSGS's LNGTBL entry for Spanish: point TBLPTR at SPNMSG for message X*2, then fall into MSTART
;   to draw it.
;------------------------------------------------------------------------------
SPANSH:
L6CAB:  LDA  SPNMSG,X
L6CAE:  STA  TBLPTR
L6CB0:  LDA  SPNMSG+1,X
L6CB3:  JMP  MSTART

;------------------------------------------------------------------------------
; FRENCH - [note] MSGS's LNGTBL entry for French: point TBLPTR at FRNMSG, then fall into MSTART.
;------------------------------------------------------------------------------
FRENCH:
L6CB6:  LDA  FRNMSG,X
L6CB9:  STA  TBLPTR
L6CBB:  LDA  FRNMSG+1,X
L6CBE:  JMP  MSTART

;------------------------------------------------------------------------------
; GERMAN - [note] MSGS's LNGTBL entry for German: point TBLPTR at GRMMSG, then fall into MSTART.
;------------------------------------------------------------------------------
GERMAN:
L6CC1:  LDA  GRMMSG,X
L6CC4:  STA  TBLPTR
L6CC6:  LDA  GRMMSG+1,X
L6CC9:  JMP  MSTART

;------------------------------------------------------------------------------
; ENGLISH - [note] MSGS's LNGTBL entry for English (OPTION language bits = 0): point TBLPTR at ENGMSG for
;   message X*2, then fall into MSTART to draw it.
;------------------------------------------------------------------------------
ENGLISH:
L6CCC:  LDA  ENGMSG,X               ;C SET UP POINTER
L6CCF:  STA  TBLPTR
L6CD1:  LDA  ENGMSG+1,X

MSTART:
L6CD4:  STA  TBLPTR+1
L6CD6:  LDY  #$00
L6CD8:  TXA
L6CD9:  CMP  #GAMOVR
L6CDB:  LDA  #$02                   ;C SET SCALING
L6CDD:  BCC  MSTART_5
L6CDF:  LDA  #$01

MSTART_5:
L6CE1:  STA  TEMP3+1
L6CE3:  LDA  (TBLPTR),Y
L6CE5:  INY                         ;D IF NO POSITIONING NEEDED
L6CE6:  ORA  (TBLPTR),Y
L6CE8:  BEQ  MSTART_10
;C POSITION FOR MSG
L6CEA:  JSR  VGCNTR
L6CED:  LDY  #$01
L6CEF:  LDA  (TBLPTR),Y
L6CF1:  TAX
L6CF2:  DEY
L6CF3:  LDA  (TBLPTR),Y
L6CF5:  JSR  VGVTR

MSTART_10:
L6CF8:  LDA  TEMP3+1
L6CFA:  JSR  VGSCA1
L6CFD:  LDY  #$02                   ;C INIT LOOP
L6CFF:  LDA  #$00                   ;C INIT VGLIST OFFSET
L6D01:  STA  TEMP1

MSTART_20:
L6D03:  LDA  (TBLPTR),Y             ;C GET CHARACTER REPRESENTATION
L6D05:  STA  TEMP2
L6D07:  AND  #$7F
L6D09:  INY
L6D0A:  STY  TEMP3                  ;SAVE Y
L6D0C:  TAX
L6D0D:  LDA  VGMSGA,X               ;C GET CORRECT JSRL
L6D10:  LDY  TEMP1
L6D12:  STA  (VGLIST),Y
L6D14:  INY
L6D15:  LDA  VGMSGA+1,X
L6D18:  STA  (VGLIST),Y
L6D1A:  INY
L6D1B:  STY  TEMP1                  ;SAVE Y
L6D1D:  LDY  TEMP3                  ;C GET CHARACTER PTR
L6D1F:  BIT  TEMP2                  ;D IF NOT END OF STRING
L6D21:  BPL  MSTART_20
L6D23:  LDY  TEMP1                  ;C UPDATE VGLIST
L6D25:  DEY
L6D26:  JSR  VGADD
L6D29:  LDA  #$01                   ;C RESET SCALE
L6D2B:  JMP  VGSCA1

;------------------------------------------------------------------------------
; INFO - INFORMATION OUTPUT
;   BLOCK NAME: INFO
;   DESCRIPTION: HANDLES MESSAGES & STATISTICS
;   INPUT PARAMS: HITS
;   OUTPUT PARAMS: NONE
;   REGISTERS: A,X,Y
;   SUBROUTINES: MSGS
;------------------------------------------------------------------------------
INFO:
L6D2E:  JSR  VGCNTR
L6D31:  LDY  #$00
L6D33:  STY  VGSIZE
L6D35:  LDX  #$5A                   ;C Y/4
L6D37:  LDA  #$20                   ;C X/4
L6D39:  JSR  VGVTR
L6D3C:  LDA  LIVES                  ;D IF DEAD
L6D3E:  BEQ  INFO_20
L6D40:  STA  TEMP1
L6D42:  LDY  #$00
L6D44:  LDX  TSYMBL+1

INFO_10:
L6D47:  LDA  TSYMBL                 ;C OUTPUT 1 TANK PER LIFE
L6D4A:  STA  (VGLIST),Y
L6D4C:  TXA
L6D4D:  INY
L6D4E:  STA  (VGLIST),Y
L6D50:  INY
L6D51:  DEC  TEMP1
L6D53:  BNE  INFO_10
L6D55:  DEY
L6D56:  JSR  VGADD

INFO_20:
L6D59:  LDX  #YSCORE
L6D5B:  JSR  MSGS
L6D5E:  LDY  #$00
L6D60:  LDX  #$00                   ;C LABS SHORT FORM (Y/4)
L6D62:  LDA  #$D6                   ;(X/4)
L6D64:  JSR  VGVTR
L6D67:  LDA  #HITS
L6D69:  JSR  DIGT2S
L6D6C:  LDX  #CHISCR
L6D6E:  JSR  MSGS
L6D71:  LDA  #$02
L6D73:  JSR  VGSCA1
L6D76:  LDY  #$00
L6D78:  LDX  #$00
L6D7A:  LDA  #$D6
L6D7C:  JSR  VGVTR
L6D7F:  LDA  HSCTBL
L6D82:  STA  TEMP2
L6D84:  LDA  HSCTBL+1
L6D87:  STA  TEMP2+1
L6D89:  LDA  #TEMP2
L6D8B:  JSR  DIGT2S
L6D8E:  LDA  #$01                   ;C RESET SCALE INFO
L6D90:  JMP  VGSCA1

