L7CAE:  STY  POKEY                  ;FREQUENCY
L7CB1:  LDA  #$09                   ;BAD
L7CB3:  CPY  #$12
L7CB5:  BEQ  STEST2_35              ;YES
L7CB7:  LDA  #$01

STEST2_35:
L7CB9:  TAY
L7CBA:  LDX  #$00

STEST2_40:
L7CBC:  BIT  HALT
L7CBF:  BMI  STEST2_40

STEST2_42:
L7CC1:  BIT  HALT
L7CC4:  BPL  STEST2_42
L7CC6:  STA  WTCHDG                 ;NO WTCHDGIN' DOG
L7CC9:  DEX
L7CCA:  BNE  STEST2_40              ;COUNT 256/3000 OF A SECOND
L7CCC:  DEY
L7CCD:  BNE  STEST2_40
L7CCF:  STX  POKEY+1                ;CLR SOUND
L7CD2:  LDY  #$09

STEST2_50:
L7CD4:  BIT  HALT
L7CD7:  BMI  STEST2_50

STEST2_52:
L7CD9:  BIT  HALT
L7CDC:  BPL  STEST2_52
L7CDE:  STA  WTCHDG                 ;NO WTCHDGDOG
