L7CE4:  DEY
L7CE5:  BNE  STEST2_50
L7CE7:  LDA  $00
L7CE9:  BNE  STEST2_60
L7CEB:  LDA  $01
L7CED:  LSR
L7CEE:  LSR
L7CEF:  LSR
L7CF0:  LSR
L7CF1:  STA  $01

STEST2_60:
