L7EC7:  LDA  OPTON2
L7ECA:  AND  #$0C
L7ECC:  LSR
L7ECD:  LSR
L7ECE:  TAX
L7ECF:  LDA  STEST8,X
L7ED2:  JSR  VGHEX                  ;DOLLAR MECH VALUE
L7ED5:  LDX  #$16                   ;(src: LDX I,88./4)
