L7EE6:  LDX  TEMP2+1
L7EE8:  TXA
L7EE9:  SEC
L7EEA:  SBC  #$08                   ;32. BELOW CURRENT LINE
L7EEC:  STA  TEMP2+1
L7EEE:  LDA  #$A0                   ;(src: LDA I,-384./4)
L7EF0:  JSR  VGVTR1                 ;POSITION BEAM
L7EF3:  LDA  TEMP2
L7EF5:  JSR  VGHEX                  ;ROM #
L7EF8:  LDA  #$06                   ;(src: LDA I,24./4)
L7EFA:  LDX  #$00
L7EFC:  JSR  VGVTR1
L7EFF:  LDA  #$00
L7F01:  LDY  #$01
L7F03:  JSR  DIGTYS                 ;DISPLAY 2 DIGITS
L7F06:  LDX  TEMP2

STEST6_30:
