;------------------------------------------------------------------------------
; DIAGDB - D IF DIAG  (comment at the call)
;   D IF NOT PUSHED  (another call)
;------------------------------------------------------------------------------
DIAGDB:
L7FB9:  LDA  HALT                   ;C CATCH EDGE
L7FBC:  TAY
L7FBD:  EOR  SAVE1
L7FBF:  AND  SAVE1
L7FC1:  STY  SAVE1
L7FC3:  AND  #$20
L7FC5:  RTS

STEST8:
